mapper.select:
SELECT bill_no, COUNT(*) segs, SUM(n) qty FROM (
  SELECT bill_no, bill_seq, seq_pi_no, g, COUNT(*) n FROM (
    SELECT bill_no, bill_seq, seq_pi_no,
      seq_dec - ROW_NUMBER() OVER (PARTITION BY bill_no, bill_seq, seq_pi_no ORDER BY seq_dec) g
    FROM sn_item WHERE pi_no = #{pi} AND origin = 'GEN' AND bill_no IN
      #{b}

  ) t GROUP BY bill_no, bill_seq, seq_pi_no, g
) u GROUP BY bill_no

mapper.sql:
FROM sn_item WHERE pi_no = #{pi} AND bill_no = #{bill} AND seq_pi_no = #{seqPi}
  AND seq_dec BETWEEN #{start} AND #{end} AND origin = 'GEN'
AND bill_seq = #{billSeq}

mapper.update:
UPDATE sn_gen_job SET status = 'SUCCESS', done_qty = qty, current_sn = end_sn, running_pi = NULL,
  finished_at = #{now}
WHERE id = #{id} AND status = 'RUNNING' AND cancel_at IS NULL

UPDATE sn_gen_job SET status = #{status}, done_qty = 0, error_code = #{code}, error_msg = #{msg},
  running_pi = NULL, finished_at = #{now}
WHERE id = #{id} AND status = 'RUNNING'

mapper.select:
SELECT sn, pi_no, origin FROM sn_item WHERE sn IN
#{s}
ORDER BY origin = 'IMPORT' DESC LIMIT 1

mapper.update:
UPDATE sn_item i JOIN (SELECT sn, MAX(rev) r FROM sn_item_deleted WHERE sn IN
  #{s}
  GROUP BY sn) d ON d.sn = i.sn
SET i.rev = d.r + 1
WHERE i.sn IN #{s}

UPDATE sn_line_count SET material_code = #{materialCode}, own_generated = own_generated + #{qty},
  gen_count = gen_count + #{qty}, updated_at = #{now}
WHERE bill_no = #{billNo} AND seq = #{seq}

UPDATE sn_pi_counter SET last_seq_dec = GREATEST(last_seq_dec, #{last}), generated_qty = generated_qty + #{qty},
  updated_at = #{now}
WHERE pi_no = #{pi}

UPDATE sn_gen_job SET status = 'FAILED', done_qty = 0, error_code = 'INTERRUPTED', error_msg = #{msg},
  running_pi = NULL, finished_at = #{now}
WHERE id = #{id}
